package desktop

import "embed"

// Icons are embedded rather than read from the source tree so a single
// installed binary can register itself on a machine that has no copy of
// the repository. Generated by tray/icon/generate.go.
//
// All forms are embedded on every platform. Each one only uses its own
// — hicolor PNGs and an SVG on Linux, the ICNS on macOS, and Windows
// takes its icon from the exe's own resources — but the few tens of
// kilobytes are not worth a build tag per file.
//
//go:embed icons/app*.png icons/godl.svg icons/godl.icns
var icons embed.FS
